369: impl OauthProtectedResourceMetadata {
370:     pub fn new(resource_url: &str, auth_issuer: &str, dpop_supported: bool) -> Self {
371:         let resource_metadata = if resource_url.ends_with("/mcp") || resource_url.ends_with("/mcp/")
372:         {
373:             let stripped = resource_url.trim_end_matches('/');
374:             Some(stripped.replace("/mcp", "/.well-known/oauth-protected-resource"))
375:         } else if resource_url.ends_with('/') {
376:             Some(format!("{}oauth-protected-resource", resource_url))
377:         } else {
378:             Some(format!("{}/oauth-protected-resource", resource_url))
379:         };
380:         Self {
381:             resource_metadata,
382:             resource: resource_url.to_string(),
383:             authorization_servers: vec![auth_issuer.to_string()],
384:             scopes_supported: vec![
385:                 "commoncal.calendar.metadata.read".to_string(),
386:                 "commoncal.availability.read".to_string(),
387:                 "commoncal.event.read.basic".to_string(),
388:                 "commoncal.event.read.details".to_string(),
389:                 "commoncal.event.create".to_string(),
390:                 "commoncal.event.update".to_string(),
391:                 "commoncal.event.delete".to_string(),
392:                 "commoncal.reminder.read".to_string(),
393:                 "commoncal.reminder.write".to_string(),
394:             ],
395:             dpop_bound_access_tokens: dpop_supported,
396:         }
397:     }
398: }
